export const hashPassword = (plain: string) => bcrypt.hash(plain, 10);
export const verifyPassword = (plain: string, hash: string) =>
  bcrypt.compare(plain, hash);

/**
 * `Authorization: Token <jwt>` (또는 Bearer) 헤더에서 토큰을 꺼낸다.
 * 헤더가 없으면 null.
 */
function extractToken(request: FastifyRequest): string | null {
  const header = request.headers.authorization;
  if (!header) return null;
  const match = /^(?:Token|Bearer)\s+(.+)$/i.exec(header.trim());
  return match ? match[1].trim() : null;
}

/** 토큰이 있으면 유저를 조회하고, 없거나 유효하지 않으면 null 을 돌려준다. */
export async function optionalUser(
  request: FastifyRequest,
): Promise<AuthUser | null> {
  const token = extractToken(request);
  if (!token) return null;
  try {
    const payload = jwt.verify(token, SECRET) as { id: number };
    const user = await prisma.user.findUnique({ where: { id: payload.id } });
    return user ?? null;
  } catch {
    return null;
  }
}

/** 인증이 필수인 라우트용. 토큰이 없으면 401 "is missing", 무효면 401 "is invalid". */
export async function requireUser(request: FastifyRequest): Promise<AuthUser> {
  const token = extractToken(request);
  if (!token) throw tokenMissing();
  let payload: { id: number };
  try {
    payload = jwt.verify(token, SECRET) as { id: number };
  } catch {
    throw tokenInvalid();
  }
  const user = await prisma.user.findUnique({ where: { id: payload.id } });
  if (!user) throw tokenInvalid();
  return user;
}

