import { unprocessable, type ErrorBody } from './errors';

/** NIST 800-63B 권고에 따른 최소 비밀번호 길이 */
export const MIN_PASSWORD_LENGTH = 8;

/** 값이 문자열이고 공백만으로 이루어지지 않았는지 */
const isBlank = (value: unknown) =>
  value === null ||
  value === undefined ||
  (typeof value === 'string' && value.trim() === '');

/** 여러 필드의 에러를 모아 한 번에 422 를 던지는 수집기 */
export class ErrorCollector {
  private readonly errors: ErrorBody = {};

  add(field: string, message: string): void {
    (this.errors[field] ??= []).push(message);
  }

  /** 필수 문자열 필드 검증. 통과하면 트림하지 않은 원본 문자열을 돌려준다. */
  requireString(field: string, value: unknown): string | null {
    if (isBlank(value) || typeof value !== 'string') {
      this.add(field, "can't be blank");
      return null;
    }
    return value;
  }

  get hasErrors(): boolean {
    return Object.keys(this.errors).length > 0;
  }

  /** 에러가 하나라도 있으면 422 예외를 던진다. */
  throwIfAny(): void {
    if (this.hasErrors) throw unprocessable(this.errors);
  }
}

/** 비밀번호 정책 검증 (blank 금지 + 최소 길이) */
export function validatePassword(
  collector: ErrorCollector,
  value: unknown,
): string | null {
  const password = collector.requireString('password', value);
  if (password === null) return null;
  if (password.length < MIN_PASSWORD_LENGTH) {
    collector.add('password', `is too short (minimum is ${MIN_PASSWORD_LENGTH} characters)`);
    return null;
  }
  return password;
}

/**
 * bio/image 처럼 nullable 인 필드를 정규화한다.
 * 빈 문자열은 null 로 바꾸고, 문자열이 아니면 null 로 취급한다.
 */
export function normalizeNullable(value: unknown): string | null {
  if (typeof value !== 'string') return null;
  return value === '' ? null : value;
}

/** 요청 본문에서 래핑 객체(user/article/comment)를 꺼낸다. 없으면 빈 객체. */
export function unwrap(body: unknown, key: string): Record<string, unknown> {
  if (body && typeof body === 'object' && key in (body as object)) {
    const inner = (body as Record<string, unknown>)[key];
    if (inner && typeof inner === 'object') return inner as Record<string, unknown>;
  }
  return {};
}

