import { signToken, type AuthUser } from './auth';

/** DB 레코드에서 프로필 응답에 필요한 최소 필드 */
export interface ProfileSource {
  username: string;
  bio: string | null;
  image: string | null;
}

/** GET /api/user 등에서 반환하는 유저 표현 (토큰 포함) */
export function toUserResponse(user: AuthUser) {
  return {
    user: {
      email: user.email,
      token: signToken(user.id),
      username: user.username,
      bio: user.bio,
      image: user.image,
    },
  };
}

/** 프로필 표현. following 은 호출자가 계산해 넘긴다. */
export function toProfile(user: ProfileSource, following: boolean) {
  return {
    username: user.username,
    bio: user.bio,
    image: user.image,
    following,
  };
}

interface ArticleSource {
  slug: string;
  title: string;
  description: string;
  body: string;
  createdAt: Date;
  updatedAt: Date;
  author: ProfileSource;
  tags: { tag: { name: string }; position: number }[];
  favorites: unknown[];
  _count: { favorites: number };
}

/**
 * 아티클 표현.
 * `includeBody` 가 false 면 body 를 제외한다 (목록 응답 스펙).
 */
export function toArticle(
  article: ArticleSource,
  followingAuthor: boolean,
  includeBody = true,
) {
  const base = {
    slug: article.slug,
    title: article.title,
    description: article.description,
    tagList: [...article.tags]
      .sort((a, b) => a.position - b.position)
      .map((t) => t.tag.name),
    createdAt: article.createdAt.toISOString(),
    updatedAt: article.updatedAt.toISOString(),
    favorited: article.favorites.length > 0,
    favoritesCount: article._count.favorites,
    author: toProfile(article.author, followingAuthor),
  };
  return includeBody ? { ...base, body: article.body } : base;
}

interface CommentSource {
  id: number;
  body: string;
  createdAt: Date;
  updatedAt: Date;
  author: ProfileSource;
}

export function toComment(comment: CommentSource, followingAuthor: boolean) {
  return {
    id: comment.id,
    createdAt: comment.createdAt.toISOString(),
    updatedAt: comment.updatedAt.toISOString(),
    body: comment.body,
    author: toProfile(comment.author, followingAuthor),
  };
}

