import type { FastifyInstance } from 'fastify';
import { prisma } from '../lib/prisma';
import { ApiError, conflict } from '../lib/errors';
import { hashPassword, requireUser, verifyPassword } from '../lib/auth';
import { toUserResponse } from '../lib/presenters';
import {
  ErrorCollector,
  normalizeNullable,
  unwrap,
  validatePassword,
} from '../lib/validation';

/** username/email 중복 여부를 확인하고 중복이면 409 를 던진다. */
async function assertUnique(
  username: string | null,
  email: string | null,
  excludeUserId?: number,
): Promise<void> {
  if (username) {
    const found = await prisma.user.findUnique({ where: { username } });
    if (found && found.id !== excludeUserId) throw conflict('username');
  }
  if (email) {
    const found = await prisma.user.findUnique({ where: { email } });
    if (found && found.id !== excludeUserId) throw conflict('email');
  }
}

export async function userRoutes(app: FastifyInstance): Promise<void> {
  // 회원가입
  app.post('/api/users', async (request, reply) => {
    const input = unwrap(request.body, 'user');
    const collector = new ErrorCollector();
    const username = collector.requireString('username', input.username);
    const email = collector.requireString('email', input.email);
    const password = validatePassword(collector, input.password);
    collector.throwIfAny();

    await assertUnique(username, email);

    const user = await prisma.user.create({
      data: {
        username: username!,
        email: email!,
        passwordHash: await hashPassword(password!),
      },
    });
    return reply.code(201).send(toUserResponse(user));
  });

  // 로그인
  app.post('/api/users/login', async (request) => {
    const input = unwrap(request.body, 'user');
    const collector = new ErrorCollector();
    const email = collector.requireString('email', input.email);
    const password = collector.requireString('password', input.password);
    collector.throwIfAny();

    const user = await prisma.user.findUnique({ where: { email: email! } });
    if (!user || !(await verifyPassword(password!, user.passwordHash))) {
      throw new ApiError(401, { credentials: ['invalid'] });
    }
    return toUserResponse(user);
  });

  // 현재 유저 조회
  app.get('/api/user', async (request) => {
    const user = await requireUser(request);
    return toUserResponse(user);
  });

  // 현재 유저 수정
  app.put('/api/user', async (request) => {
    const current = await requireUser(request);
    const input = unwrap(request.body, 'user');
    const collector = new ErrorCollector();

    // username/email/password 는 키가 존재할 때만 검증하며 blank 를 허용하지 않는다.
    const username =
      'username' in input ? collector.requireString('username', input.username) : null;
    const email = 'email' in input ? collector.requireString('email', input.email) : null;
    const password =
      'password' in input ? validatePassword(collector, input.password) : null;
    collector.throwIfAny();

    await assertUnique(username, email, current.id);

    // bio/image 는 nullable — 빈 문자열은 null 로 정규화한다.
    const user = await prisma.user.update({
      where: { id: current.id },
      data: {
        ...(username ? { username } : {}),
        ...(email ? { email } : {}),
        ...(password ? { passwordHash: await hashPassword(password) } : {}),
        ...('bio' in input ? { bio: normalizeNullable(input.bio) } : {}),
        ...('image' in input ? { image: normalizeNullable(input.image) } : {}),
      },
    });
    return toUserResponse(user);
  });
}

