import type { FastifyInstance } from 'fastify';
import { prisma } from '../lib/prisma';
import { notFound } from '../lib/errors';
import { optionalUser, requireUser } from '../lib/auth';
import { toProfile } from '../lib/presenters';

/** followerId 가 followedId 를 팔로우 중인지 */
export async function isFollowing(
  followerId: number | undefined,
  followedId: number,
): Promise<boolean> {
  if (!followerId) return false;
  const follow = await prisma.follow.findUnique({
    where: { followerId_followedId: { followerId, followedId } },
  });
  return follow !== null;
}

/** username 으로 유저를 찾고, 없으면 404 profile not found */
async function findProfileOr404(username: string) {
  const user = await prisma.user.findUnique({ where: { username } });
  if (!user) throw notFound('profile');
  return user;
}

export async function profileRoutes(app: FastifyInstance): Promise<void> {
  // 프로필 조회 (인증 선택)
  app.get<{ Params: { username: string } }>(
    '/api/profiles/:username',
    async (request) => {
      const viewer = await optionalUser(request);
      const target = await findProfileOr404(request.params.username);
      return { profile: toProfile(target, await isFollowing(viewer?.id, target.id)) };
    },
  );

  // 팔로우
  app.post<{ Params: { username: string } }>(
    '/api/profiles/:username/follow',
    async (request) => {
      const viewer = await requireUser(request);
      const target = await findProfileOr404(request.params.username);
      if (target.id !== viewer.id) {
        await prisma.follow.upsert({
          where: { followerId_followedId: { followerId: viewer.id, followedId: target.id } },
          create: { followerId: viewer.id, followedId: target.id },
          update: {},
        });
      }
      return { profile: toProfile(target, target.id !== viewer.id) };
    },
  );

  // 언팔로우
  app.delete<{ Params: { username: string } }>(
    '/api/profiles/:username/follow',
    async (request) => {
      const viewer = await requireUser(request);
      const target = await findProfileOr404(request.params.username);
      await prisma.follow.deleteMany({
        where: { followerId: viewer.id, followedId: target.id },
      });
      return { profile: toProfile(target, false) };
    },
  );
}

