import type { FastifyInstance } from 'fastify';
import { prisma } from '../lib/prisma';
import { forbidden, notFound, unprocessable } from '../lib/errors';
import { optionalUser, requireUser, type AuthUser } from '../lib/auth';
import { toArticle } from '../lib/presenters';
import { ErrorCollector, unwrap } from '../lib/validation';

/** 제목을 URL 안전한 슬러그로 바꾼다. */
function slugify(title: string): string {
  const base = title
    .toLowerCase()
    .normalize('NFKD')
    .replace(/[^a-z0-9]+/g, '-')
    .replace(/^-+|-+$/g, '');
  return base || 'article';
}

/** 제목이 중복돼도 충돌하지 않도록 임의 접미사를 붙인 슬러그를 만든다. */
async function makeUniqueSlug(title: string): Promise<string> {
  const base = slugify(title);
  for (let attempt = 0; attempt < 20; attempt += 1) {
    const suffix = Math.random().toString(36).slice(2, 8);
    const slug = `${base}-${suffix}`;
    const exists = await prisma.article.findUnique({ where: { slug } });
    if (!exists) return slug;
  }
  throw new Error('고유한 슬러그를 생성하지 못했습니다');
}

/** 아티클 응답에 필요한 관계를 모두 로드하는 include 절 */
function articleInclude(viewerId?: number) {
  return {
    author: true,
    tags: { include: { tag: true } },
    // 조회자가 즐겨찾기했는지 확인용 — 비로그인은 어떤 행에도 매치되지 않는 조건을 쓴다.
    favorites: { where: { userId: viewerId ?? -1 } },
    _count: { select: { favorites: true } },
  } as const;
}

/** 조회자가 팔로우 중인 저자 id 집합 */
async function followedAuthorIds(viewerId?: number): Promise<Set<number>> {
  if (!viewerId) return new Set();
  const rows = await prisma.follow.findMany({ where: { followerId: viewerId } });
  return new Set(rows.map((r) => r.followedId));
}

/** tagList 를 검증하고 문자열 배열로 정규화한다. 잘못된 값이면 422. */
function parseTagList(value: unknown): string[] {
  if (!Array.isArray(value) || value.some((t) => typeof t !== 'string')) {
    throw unprocessable({ tagList: ['is invalid'] });
  }
  // 중복 태그는 제거하되 입력 순서는 보존한다.
  return [...new Set(value as string[])];
}

/** 아티클에 태그를 연결한다. 기존 연결은 모두 지운다. */
async function setTags(articleId: number, tagNames: string[]): Promise<void> {
  await prisma.articleTag.deleteMany({ where: { articleId } });
  for (const [position, name] of tagNames.entries()) {
    const tag = await prisma.tag.upsert({
      where: { name },
      create: { name },
      update: {},
    });
    await prisma.articleTag.create({ data: { articleId, tagId: tag.id, position } });
  }
}

/** slug 로 아티클을 찾고 없으면 404 article not found */
async function findArticleOr404(slug: string, viewerId?: number) {
  const article = await prisma.article.findUnique({
    where: { slug },
    include: articleInclude(viewerId),
  });
  if (!article) throw notFound('article');
  return article;
}

/** 아티클 하나를 응답 형태로 감싼다. */
async function respondArticle(
  article: Awaited<ReturnType<typeof findArticleOr404>>,
  viewer: AuthUser | null,
) {
  const followed = await followedAuthorIds(viewer?.id);
  return { article: toArticle(article, followed.has(article.authorId)) };
}

/** limit/offset 쿼리 파라미터를 파싱한다. */
function parsePaging(query: Record<string, string | undefined>) {
  const limit = Number.parseInt(query.limit ?? '', 10);
  const offset = Number.parseInt(query.offset ?? '', 10);
  return {
    take: Number.isFinite(limit) && limit >= 0 ? limit : 20,
    skip: Number.isFinite(offset) && offset >= 0 ? offset : 0,
  };
}

export async function articleRoutes(app: FastifyInstance): Promise<void> {
  // 아티클 목록 (인증 선택)
  app.get<{ Querystring: Record<string, string | undefined> }>(
    '/api/articles',
    async (request) => {
      const viewer = await optionalUser(request);
      const { tag, author, favorited } = request.query;
      const { take, skip } = parsePaging(request.query);

      const where = {
        ...(tag ? { tags: { some: { tag: { name: tag } } } } : {}),
        ...(author ? { author: { username: author } } : {}),
        ...(favorited ? { favorites: { some: { user: { username: favorited } } } } : {}),
      };

      const [articles, articlesCount] = await Promise.all([
        prisma.article.findMany({
          where,
          include: articleInclude(viewer?.id),
          orderBy: [{ createdAt: 'desc' }, { id: 'desc' }],
          take,
          skip,
        }),
        prisma.article.count({ where }),
      ]);

      const followed = await followedAuthorIds(viewer?.id);
      return {
        articles: articles.map((a) => toArticle(a, followed.has(a.authorId), false)),
        articlesCount,
      };
    },
  );

  // 피드 — 팔로우 중인 저자들의 아티클 (인증 필수)
  app.get<{ Querystring: Record<string, string | undefined> }>(
    '/api/articles/feed',
    async (request) => {
      const viewer = await requireUser(request);
      const { take, skip } = parsePaging(request.query);
      const followed = await followedAuthorIds(viewer.id);
      const where = { authorId: { in: [...followed] } };

      const [articles, articlesCount] = await Promise.all([
        prisma.article.findMany({
          where,
          include: articleInclude(viewer.id),
          orderBy: [{ createdAt: 'desc' }, { id: 'desc' }],
          take,
          skip,
        }),
        prisma.article.count({ where }),
      ]);

      return {
        articles: articles.map((a) => toArticle(a, followed.has(a.authorId), false)),
        articlesCount,
      };
    },
  );

  // 아티클 단건 조회 (인증 선택)
  app.get<{ Params: { slug: string } }>('/api/articles/:slug', async (request) => {
    const viewer = await optionalUser(request);
    const article = await findArticleOr404(request.params.slug, viewer?.id);
    return respondArticle(article, viewer);
  });

  // 아티클 생성
  app.post('/api/articles', async (request, reply) => {
    const viewer = await requireUser(request);
    const input = unwrap(request.body, 'article');
    const collector = new ErrorCollector();
    const title = collector.requireString('title', input.title);
    const description = collector.requireString('description', input.description);
    const body = collector.requireString('body', input.body);
    collector.throwIfAny();

    const tagNames = 'tagList' in input ? parseTagList(input.tagList) : [];
    const created = await prisma.article.create({
      data: {
        slug: await makeUniqueSlug(title!),
        title: title!,
        description: description!,
        body: body!,
        authorId: viewer.id,
      },
    });
    await setTags(created.id, tagNames);

    const article = await findArticleOr404(created.slug, viewer.id);
    return reply.code(201).send(await respondArticle(article, viewer));
  });

  // 아티클 수정 (작성자만)
  app.put<{ Params: { slug: string } }>('/api/articles/:slug', async (request) => {
    const viewer = await requireUser(request);
    const existing = await findArticleOr404(request.params.slug, viewer.id);
    if (existing.authorId !== viewer.id) throw forbidden('article');

    const input = unwrap(request.body, 'article');
    const collector = new ErrorCollector();
    const title = 'title' in input ? collector.requireString('title', input.title) : null;
    const description =
      'description' in input
        ? collector.requireString('description', input.description)
        : null;
    const body = 'body' in input ? collector.requireString('body', input.body) : null;
    collector.throwIfAny();

    // tagList 를 명시적으로 보낸 경우에만 태그를 교체한다 (미지정 시 기존 태그 유지).
    if ('tagList' in input) await setTags(existing.id, parseTagList(input.tagList));

    await prisma.article.update({
      where: { id: existing.id },
      data: {
        ...(title ? { title } : {}),
        ...(description ? { description } : {}),
        ...(body ? { body } : {}),
        updatedAt: new Date(),
      },
    });

    const article = await findArticleOr404(existing.slug, viewer.id);
    return respondArticle(article, viewer);
  });

  // 아티클 삭제 (작성자만)
  app.delete<{ Params: { slug: string } }>(
    '/api/articles/:slug',
    async (request, reply) => {
      const viewer = await requireUser(request);
      const existing = await findArticleOr404(request.params.slug, viewer.id);
      if (existing.authorId !== viewer.id) throw forbidden('article');
      await prisma.article.delete({ where: { id: existing.id } });
      return reply.code(204).send();
    },
  );

  // 즐겨찾기 추가
  app.post<{ Params: { slug: string } }>(
    '/api/articles/:slug/favorite',
    async (request) => {
      const viewer = await requireUser(request);
      const existing = await findArticleOr404(request.params.slug, viewer.id);
      await prisma.favorite.upsert({
        where: { userId_articleId: { userId: viewer.id, articleId: existing.id } },
        create: { userId: viewer.id, articleId: existing.id },
        update: {},
      });
      return respondArticle(await findArticleOr404(existing.slug, viewer.id), viewer);
    },
  );

  // 즐겨찾기 해제
  app.delete<{ Params: { slug: string } }>(
    '/api/articles/:slug/favorite',
    async (request) => {
      const viewer = await requireUser(request);
      const existing = await findArticleOr404(request.params.slug, viewer.id);
      await prisma.favorite.deleteMany({
        where: { userId: viewer.id, articleId: existing.id },
      });
      return respondArticle(await findArticleOr404(existing.slug, viewer.id), viewer);
    },
  );
}

