import type { FastifyInstance } from 'fastify';
import { prisma } from '../lib/prisma';
import { forbidden, notFound } from '../lib/errors';
import { optionalUser, requireUser } from '../lib/auth';
import { toComment } from '../lib/presenters';
import { ErrorCollector, unwrap } from '../lib/validation';
import { isFollowing } from './profiles';

/** slug 로 아티클을 찾고 없으면 404 article not found */
async function findArticleOr404(slug: string) {
  const article = await prisma.article.findUnique({ where: { slug } });
  if (!article) throw notFound('article');
  return article;
}

export async function commentRoutes(app: FastifyInstance): Promise<void> {
  // 코멘트 목록 (인증 선택)
  app.get<{ Params: { slug: string } }>(
    '/api/articles/:slug/comments',
    async (request) => {
      const viewer = await optionalUser(request);
      const article = await findArticleOr404(request.params.slug);
      const comments = await prisma.comment.findMany({
        where: { articleId: article.id },
        include: { author: true },
        orderBy: { id: 'asc' },
      });
      const followed = viewer
        ? new Set(
            (await prisma.follow.findMany({ where: { followerId: viewer.id } })).map(
              (f) => f.followedId,
            ),
          )
        : new Set<number>();
      return {
        comments: comments.map((c) => toComment(c, followed.has(c.authorId))),
      };
    },
  );

  // 코멘트 작성
  app.post<{ Params: { slug: string } }>(
    '/api/articles/:slug/comments',
    async (request, reply) => {
      const viewer = await requireUser(request);
      const article = await findArticleOr404(request.params.slug);
      const input = unwrap(request.body, 'comment');
      const collector = new ErrorCollector();
      const body = collector.requireString('body', input.body);
      collector.throwIfAny();

      const comment = await prisma.comment.create({
        data: { body: body!, articleId: article.id, authorId: viewer.id },
        include: { author: true },
      });
      return reply
        .code(201)
        .send({ comment: toComment(comment, await isFollowing(viewer.id, comment.authorId)) });
    },
  );

  // 코멘트 삭제 (작성자만)
  app.delete<{ Params: { slug: string; id: string } }>(
    '/api/articles/:slug/comments/:id',
    async (request, reply) => {
      const viewer = await requireUser(request);
      const article = await findArticleOr404(request.params.slug);
