import Fastify, { type FastifyInstance } from 'fastify';
import { ApiError } from './lib/errors';
import { userRoutes } from './routes/users';
import { profileRoutes } from './routes/profiles';
import { articleRoutes } from './routes/articles';
import { commentRoutes } from './routes/comments';
import { tagRoutes } from './routes/tags';

/** Fastify 인스턴스를 만들고 모든 라우트와 에러 핸들러를 등록한다. */
export function buildApp(options: { logger?: boolean } = {}): FastifyInstance {
  const app = Fastify({ logger: options.logger ?? false });

  // 본문 없이 오는 POST/DELETE(즐겨찾기, 팔로우 등)를 위해 빈 본문을 허용한다.
  app.addContentTypeParser(
    '*',
    { parseAs: 'string' },
    (_request, payload: string, done) => {
      if (!payload) return done(null, undefined);
      try {
        done(null, JSON.parse(payload));
      } catch {
        done(null, undefined);
      }
    },
  );

  app.register(userRoutes);
  app.register(profileRoutes);
  app.register(articleRoutes);
  app.register(commentRoutes);
  app.register(tagRoutes);

  // 모든 에러를 RealWorld 포맷 { errors: { 필드: [메시지] } } 으로 변환한다.
  app.setErrorHandler((error, _request, reply) => {
    if (error instanceof ApiError) {
      return reply.code(error.statusCode).send({ errors: error.errors });
    }
    app.log.error(error);
    return reply.code(500).send({ errors: { body: ['internal server error'] } });
  });

  // 정의되지 않은 경로
  app.setNotFoundHandler((_request, reply) =>
    reply.code(404).send({ errors: { route: ['not found'] } }),
  );

  return app;
}

